const D = { density:.5, thresh:.52, energy:.6, speed:1, scale:1, warp:.28, hue:210, x:.5, y:.5, style:'databend', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const style = P.style;
const horizontal = (style === 'vhs' || style === 'scanbend');
// coarse buffer (image()-upscaled); keep pixel budget modest for per-frame sort
const BW = 240, BH = Math.max(64, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  const N = BW * BH;
  S.sr = new Float32Array(N); S.sg = new Float32Array(N); S.sb = new Float32Array(N); S.bl = new Float32Array(N);
  S.idx = new Int32Array(Math.max(BW, BH));
}
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.o1 = fr(1) * 40; S.o2 = fr(2) * 40; S.hoff = fr(3);
}
const sd = (P.seed | 0);
function hsh(ix, iy) { let h = (ix * 374761393 + iy * 668265263 + sd * 2147483647) | 0; h = (h ^ (h >> 13)) * 1274126177 | 0; return ((h ^ (h >> 16)) >>> 0) / 4294967295; }
function vn(x, y) { const ix = Math.floor(x), iy = Math.floor(y), fx = x - ix, fy = y - iy; const uu = fx*fx*(3-2*fx), vv = fy*fy*(3-2*fy); const a = hsh(ix,iy), b = hsh(ix+1,iy), c = hsh(ix,iy+1), d = hsh(ix+1,iy+1); return a + (b-a)*uu + (c-a)*vv + (a-b-c+d)*uu*vv; }
function fbm(x, y) { return 0.6*vn(x,y) + 0.27*vn(x*2.03+5.1, y*2.03-3.2) + 0.13*vn(x*4.1-2.3, y*4.1+7.7); }

const tt = K.t * (0.05 + P.speed * 0.11);
const zoom = 3.2 / (0.4 + P.scale * 1.2);
const W = 0.4 + P.warp * 2.6;
const sec = K.section;
const hb = ((P.hue + S.hoff * 60 + sec * 21) % 360 + 360) % 360;
const expo = 0.5 + P.energy * 0.95 + K.intensity * 0.3 + A.rms * 0.6;
const bands = 3.0 + P.density * 12.0;              // colour-band frequency (finer = more streaks)
// iq cosine palette
function pal(m, off) { const hr = hb/360 + off; return [
  0.5 + 0.5*Math.cos(6.2831*(m + hr + 0.00)),
  0.5 + 0.5*Math.cos(6.2831*(m + hr + 0.33)),
  0.5 + 0.5*Math.cos(6.2831*(m + hr + 0.66)) ]; }

// ---- 1. synth a colourful source field into S.sr/sg/sb + brightness S.bl ----
const sr = S.sr, sg = S.sg, sb = S.sb, bl = S.bl;
const panX = S.o1 + (P.x - 0.5) * zoom * 2.0, panY = S.o2 + (P.y - 0.5) * zoom * 2.0;
for (let j = 0; j < BH; j++) {
  const ny = (j / BH - 0.5) * zoom + panY;
  for (let i = 0; i < BW; i++) {
    const idx = j * BW + i;
    const nx = (i / BW - 0.5) * zoom * (BW / BH) + panX;
    const qx = fbm(nx + tt*0.5, ny*1.0), qy = fbm(nx + 3.3, ny - tt*0.4 + 1.7);
    let v0 = fbm(nx + W*qx, ny + W*qy - tt*0.2);
    // add mid-frequency structure so brightness spans vary in length (organic glitch, not smooth stripes)
    const detail = vn(nx*3.1 + 11.0, ny*3.1 - tt*0.3);
    let v = v0*0.62 + detail*0.38;
    v = Math.min(1, Math.max(0, (v - 0.5) * (1.15 + P.energy*0.85) + 0.5)); // sharpen contrast -> more tears
    const grad = (i / BW);                          // horizontal ramp adds spectral drift
    // HUE depends mainly on ROW position (near-horizontal rainbow bands) so the vertical sort drags colour into clean drips
    const rowPhase = j / BH;
    const huePhase = rowPhase * 1.5 * bands + v * 0.18 * bands + grad * 0.35 + tt * 0.13;
    const sh = 0.16 + 0.98 * v * expo;              // deeper darks / brighter brights -> smears pop
    let r, g2, b2;
    if (style === 'mono') {
      // high-contrast black/white sorted static — bulletproof linear map, always visible
      const s = 0.1 + 0.85 * Math.min(1, Math.max(0, (v - 0.3) * 1.5 + 0.35));
      r = g2 = b2 = s;
    } else if (style === 'thermal') {
      const m = Math.min(1, v * expo * 1.35);
      r = Math.min(1, m*2.1); g2 = Math.min(1, Math.max(0, m*2.0-0.55)); b2 = Math.min(1, Math.max(0, m*3.4-2.3));
    } else if (style === 'chromatic') {
      const c = pal((huePhase * 0.7) % 1, 0);
      const s2 = 0.32 + 0.85 * v * expo;
      r = c[0]*s2; g2 = c[1]*s2; b2 = c[2]*s2;
    } else if (style === 'vhs') {
      const c = pal((huePhase * 0.75) % 1, 0.12);
      const s2 = 0.34 + 0.8 * v * expo;
      r = Math.min(1, c[0]*s2*1.15); g2 = c[1]*s2*0.9; b2 = Math.min(1, c[2]*s2*1.2);
    } else { // databend (default) — full-spectrum
      const c = pal(huePhase % 1, 0);
      r = c[0]*sh; g2 = c[1]*sh; b2 = c[2]*sh;
    }
    sr[idx] = r; sg[idx] = g2; sb[idx] = b2;
    bl[idx] = 0.299*r + 0.587*g2 + 0.114*b2;
  }
}

// ---- 2. pixel-sort spans whose brightness is inside a moving threshold window ----
// window drifts on K.t so the sort perpetually re-melts (real-time motion floor)
const centre = 0.42 + 0.16 * Math.sin(K.t * (0.10 + P.speed*0.12)) + A.bass * 0.12;
const halfw = 0.06 + P.thresh * 0.42;               // wider thresh = more of the frame melts
const lo = centre - halfw, hi = centre + halfw;
const ascending = (Math.floor(K.t * (0.05 + P.speed*0.05)) % 2 === 0); // slowly flips sort dir
const idxArr = S.idx;

function sortLine(get, set, len) {
  let s = 0;
  while (s < len) {
    if (get(s) < lo || get(s) > hi) { s++; continue; }
    let e = s;
    while (e < len && get(e) >= lo && get(e) <= hi) e++;   // [s,e) is a sortable span
    const n = e - s;
    if (n > 1) {
      for (let k = 0; k < n; k++) idxArr[k] = s + k;
      // sort indices by brightness
      const sub = Array.prototype.slice.call(idxArr, 0, n);
      sub.sort((a, b) => ascending ? (get(a) - get(b)) : (get(b) - get(a)));
      // capture originals then rewrite in sorted order
      set(s, n, sub);
    }
    s = e;
  }
}

const tmpR = S._tr || (S._tr = new Float32Array(Math.max(BW, BH)));
const tmpG = S._tg || (S._tg = new Float32Array(Math.max(BW, BH)));
const tmpB = S._tb || (S._tb = new Float32Array(Math.max(BW, BH)));

if (!horizontal) {
  for (let i = 0; i < BW; i++) {
    const base = i;
    const get = k => bl[(k) * BW + base];
    const set = (start, n, order) => {
      for (let k = 0; k < n; k++) { const o = order[k]; tmpR[k]=sr[o*BW+base]; tmpG[k]=sg[o*BW+base]; tmpB[k]=sb[o*BW+base]; }
      for (let k = 0; k < n; k++) { const p=(start+k)*BW+base; sr[p]=tmpR[k]; sg[p]=tmpG[k]; sb[p]=tmpB[k]; }
    };
    sortLine(get, set, BH);
  }
} else {
  for (let j = 0; j < BH; j++) {
    const row = j * BW;
    const get = k => bl[row + k];
    const set = (start, n, order) => {
      for (let k = 0; k < n; k++) { const o = order[k]; tmpR[k]=sr[row+o]; tmpG[k]=sg[row+o]; tmpB[k]=sb[row+o]; }
      for (let k = 0; k < n; k++) { const p=row+start+k; sr[p]=tmpR[k]; sg[p]=tmpG[k]; sb[p]=tmpB[k]; }
    };
    sortLine(get, set, BW);
  }
}

// ---- 3. blit to pixels ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const chroma = (style === 'chromatic' || style === 'vhs') ? Math.round(1 + A.treble*4 + P.warp*3) : 0;
for (let j = 0; j < BH; j++) {
  for (let i = 0; i < BW; i++) {
    const idx = j*BW + i;
    let ri = idx, bi = idx;
    if (chroma) { const rj = Math.min(BW-1, i+chroma), bj = Math.max(0, i-chroma); ri = j*BW+rj; bi = j*BW+bj; }
    const p = idx*4;
    px[p]   = Math.max(0, Math.min(255, sr[ri]*255));
    px[p+1] = Math.max(0, Math.min(255, sg[idx]*255));
    px[p+2] = Math.max(0, Math.min(255, sb[bi]*255));
    px[p+3] = 255;
  }
}
g.updatePixels();

// scanline overlay for vhs/scanbend
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
if (style === 'vhs' || style === 'scanbend') {
  push(); blendMode(MULTIPLY); noStroke();
  const sl = Math.max(2, Math.round(height/220));
  for (let y = 0; y < height; y += sl*2) { fill(0,0,0, 24); rect(0, y, width, sl); }
  pop();
}
